            const getCurrentFormData = () => { const data = {}; allInputs.forEach(input => { const key = input.id || input.name; if(key) data[key] = input.value; }); data['start-location'] = locationSelect.value === 'custom' ? customLocationInput.value : locationSelect.value; data['char-background'] = backgroundSelect.value === 'custom' ? customBackgroundInput.value : backgroundSelect.value; return data; };
            const populateForm = (data) => { if (!data) return; form.reset(); allInputs.forEach(input => { const key = input.id || input.name; if (data[key] !== undefined && input.type !== 'select-one') { input.value = data[key]; } }); const setupCustomSelect = (select, container, input, value) => { const options = Array.from(select.options).map(opt => opt.value); if (options.includes(value)) { select.value = value; } else if (value) { select.value = 'custom'; input.value = value; } select.dispatchEvent(new Event('change')); }; setupCustomSelect(locationSelect, customLocationContainer, customLocationInput, data['start-location']); setupCustomSelect(backgroundSelect, customBackgroundContainer, customBackgroundInput, data['char-background']); allInputs.forEach(input => { if (input.type === 'select-one' && !input.id.includes('location') && !input.id.includes('background') && data[input.id]) { input.value = data[input.id]; } }); };
