            const populateDropdown = () => { const profiles = getProfiles(); const profileNames = Object.keys(profiles); profileSelect.innerHTML = ''; if (profileNames.length === 0) { profileSelect.innerHTML = '<option value="">-- 尚无已存方案 --</option>'; loadProfileBtn.disabled = true; deleteProfileBtn.disabled = true; exportProfilesBtn.disabled = true; } else { profileSelect.innerHTML = '<option value="">-- 选择一个方案 --</option>'; profileNames.sort().forEach(name => { const option = document.createElement('option'); option.value = name; option.textContent = name; profileSelect.appendChild(option); }); loadProfileBtn.disabled = false; deleteProfileBtn.disabled = false; exportProfilesBtn.disabled = false; } };
