            resetFormBtn.addEventListener('click', () => { if (confirm('确定要清空当前所有填写的内容，并将表单重置为默认状态吗？')) { form.reset(); locationSelect.dispatchEvent(new Event('change')); backgroundSelect.dispatchEvent(new Event('change')); debouncedAutoSave(); showNotification('表单已重置为默认状态。', 'var(--accent-color)'); } });

