          showEventsBtn: document.getElementById('show-events-btn'), eventsModal: document.getElementById('events-modal'), closeModalBtn: document.querySelector('.era-modal-close-btn'), eventsContent: document.getElementById('events-content'),
          reincarnationCount: document.getElementById('reincarnation-count'),
          clothingOutfit: document.getElementById('clothing-outfit'), clothingFootwear: document.getElementById('clothing-footwear'), clothingAccessory: document.getElementById('clothing-accessory'), clothingRestraint: document.getElementById('clothing-restraint'),
