          elements.clothingRestraint.textContent = _.get(stat, '服饰.拘束', '--');

          elements.featureATitle.textContent = _.get(stat, '临时.特写.特写_1.部位', '--');
          elements.featureAContent.textContent = _.get(stat, '临时.特写.特写_1.描述', '--');
          elements.featureBTitle.textContent = _.get(stat, '临时.特写.特写_2.部位', '--');
          elements.featureBContent.textContent = _.get(stat, '临时.特写.特写_2.描述', '--');
          elements.featureCTitle.textContent = _.get(stat, '临时.特写.特写_3.部位', '--');
          elements.featureCContent.textContent = _.get(stat, '临时.特写.特写_3.描述', '--');

          elements.inventoryTitleLabel.textContent = `📦 ${charName}的物品`;
          const inventoryData = _.get(stat, '物品栏');
          let invChildren = elements.inventoryWrapper.children; for (let i = invChildren.length - 1; i >= 0; i--) { const child = invChildren[i]; if (child.id !== 'item-template' && child.id !== 'inventory-empty-text') { elements.inventoryWrapper.removeChild(child); } }
          let itemCount = 0; if (inventoryData && typeof inventoryData === 'object') { for (const key in inventoryData) { if (Object.hasOwnProperty.call(inventoryData, key)) { itemCount++; const item = inventoryData[key]; const itemName = _.get(item, '物品名', '未知物品'); const itemDesc = _.get(item, '描述', '没有描述。');
            const newItemElement = elements.itemTemplate.cloneNode(true); newItemElement.removeAttribute('id'); newItemElement.style.display = 'flex'; const nameElement = newItemElement.querySelector('.inventory-item-name'); const descElement = newItemElement.querySelector('.inventory-item-desc');
            if (nameElement) nameElement.textContent = itemName; if (descElement) descElement.textContent = itemDesc; elements.inventoryWrapper.appendChild(newItemElement);
          } } }
          elements.inventoryEmptyText.style.display = (itemCount === 0) ? 'block' : 'none';

          const statusData = _.get(stat, '状态');
          let statusChildren = elements.statusWrapper.children; for (let i = statusChildren.length - 1; i >= 0; i--) { const child = statusChildren[i]; if (child.id !== 'status-template' && child.id !== 'status-empty-text') { elements.statusWrapper.removeChild(child); } }
          let statusCount = 0; if (statusData && typeof statusData === 'object') { for (const key in statusData) { if (Object.hasOwnProperty.call(statusData, key)) { statusCount++; const status = statusData[key]; const statusName = _.get(status, '状态名', '未知状态'); const statusDesc = _.get(status, '描述', '没有描述。');
            const newStatusElement = elements.statusTemplate.cloneNode(true); newStatusElement.removeAttribute('id'); newStatusElement.style.display = 'flex'; const nameElement = newStatusElement.querySelector('.status-item-name'); const descElement = newStatusElement.querySelector('.status-item-desc');
            if (nameElement) nameElement.textContent = statusName; if (descElement) descElement.textContent = statusDesc; elements.statusWrapper.appendChild(newStatusElement);
          } } }
          elements.statusEmptyText.style.display = (statusCount === 0) ? 'block' : 'none';


          const loopCount = _.get(stat, '轮回回溯.次数', '0');
          elements.reincarnationCount.textContent = `回溯已发动 ${loopCount} 次`;
          const pastEvents = _.get(stat, '轮回回溯.回溯事件');
          elements.eventsContent.innerHTML = '';
          if (pastEvents && typeof pastEvents === 'object' && Object.keys(pastEvents).length > 0) {
            for (const key in pastEvents) { if (Object.hasOwnProperty.call(pastEvents, key)) {
                const eventObj = pastEvents[key]; const eventTitle = _.get(eventObj, '标题', '无标题事件'); const eventContent = _.get(eventObj, '内容', '此事件没有详细内容。');
                const itemWrapper = document.createElement('div'); itemWrapper.className = 'event-item'; const titleElement = document.createElement('h4'); titleElement.className = 'event-title'; titleElement.textContent = eventTitle;
