<!DOCTYPE html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>档案生成器 v4.2 (世界观增强版)</title>
    <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css">
    <style>
        @import url('https://fonts.googleapis.com/css2?family=Noto+Serif+SC:wght@400;600&display=swap');
        :root{
            --bg-color: #FFEBEE;
            --card-bg: #FCE4EC;
            --border-color: #F8BBD0;
            --text-color: #4E342E;
            --text-secondary: #795548;
            --accent-color: #E91E63;
            --accent-glow: rgba(233, 30, 99, 0.4);
            --error-color: #c62828;
            --success-color: #2e7d32;
            --font-family: 'Noto Serif SC', serif;
            --border-width: 2px;
        }

        body, html { scroll-behavior: smooth; }
        body { background-color: var(--bg-color); background: linear-gradient(135deg, var(--bg-color) 0%, #F4E3E5 100%); min-height: 20vh; min-width: 200px; }
        .creator-card-container{font-family:var(--font-family);background-color:transparent;color:var(--text-color);padding:clamp(5px, 2vw, 10px);font-size:clamp(14px, 3vw, 15px);max-width:800px;margin:auto}
        .creator-card{background: var(--card-bg);border:var(--border-width) solid var(--border-color);border-radius:12px;padding:clamp(15px, 4vw, 30px);box-shadow:0 0 30px -5px var(--accent-glow);backdrop-filter:blur(10px);transition:all .5s ease; position: relative;}
        .creator-card header{text-align:center;margin-bottom:20px;border-bottom:1px solid var(--border-color);padding-bottom:15px}
        .creator-card h2{margin:0;font-size:clamp(1.4em, 4vw, 1.6em);font-weight:600;color:var(--accent-color);text-shadow:0 0 10px var(--accent-glow);transition:all .3s ease; display: flex; align-items: center; justify-content: center; gap: 10px;}
        .profile-manager { margin-bottom: 25px; padding: 15px; background: rgba(255,255,255,0.2); border: var(--border-width) solid var(--border-color); border-radius: 8px; display: flex; flex-direction: column; gap: 12px; }
        .profile-manager-row { display: flex; flex-wrap: wrap; gap: 12px; align-items: center; }
        .profile-manager-group { display: flex; width: 100%; gap: 5px; }
        .manager-btn { flex: 1 1 0; font-size: clamp(0.85em, 2.5vw, 0.9em); padding: 10px 5px; border: var(--border-width) solid var(--border-color); border-radius: 6px; background: rgba(255,255,255,0.3); color: var(--text-secondary); cursor: pointer; transition: all 0.2s ease; display: inline-flex; align-items: center; justify-content: center; gap: 6px; min-width: 0; text-align: center; }
        .manager-btn:hover { background: rgba(255,255,255,0.6); color: var(--text-color); border-color: var(--accent-color); transform: translateY(-1px); }
        .manager-btn:disabled { opacity: 0.6; cursor: not-allowed; }
        #profile-select { flex-grow: 1; min-width: 150px; }
        #save-profile-btn { color: var(--success-color); } #save-profile-btn:hover { border-color: var(--success-color); }
        #delete-profile-btn { color: var(--error-color); } #delete-profile-btn:hover { border-color: var(--error-color); }

        .form-section{margin-bottom:25px}
        .form-section legend{font-size:clamp(1.1em, 3.5vw, 1.2em);font-weight:600;color:var(--text-color);border-bottom:1px solid var(--accent-color);padding-bottom:5px;margin-bottom:15px;width:100%}
        .form-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:15px 25px}
        .form-group{display:flex;flex-direction:column}
        .form-group.full-width{grid-column:1/-1}
        .form-group label{margin-bottom:8px;color:var(--text-secondary);font-size:.9em;}
        .form-group input, .form-group textarea, .form-group select, #profile-select { background: rgba(248, 187, 208, 0.2); border:var(--border-width) solid var(--border-color);border-radius:6px;padding:10px;color:var(--text-color);font-family:inherit;font-size:1em;transition:all .2s ease-in-out; word-wrap: break-word; }
        .form-group input:focus, .form-group textarea:focus, .form-group select:focus, #profile-select:focus { outline:none;border-color:var(--accent-color);box-shadow:0 0 10px -2px var(--accent-glow) }
        .input-with-button { display: flex; gap: 10px; align-items: center; }
        .input-with-button select { flex-grow: 1; }
        .label-with-button { display: flex; justify-content: space-between; align-items: center; margin-bottom: 8px;}
        .label-with-button label { margin-bottom: 0; }
        .icon-btn { padding: 10px 12px; font-size: 1.1em; border: var(--border-width) solid var(--border-color); background: rgba(255,255,255,0.3); color: var(--text-secondary); cursor: pointer; border-radius: 6px; transition: all 0.2s ease; }
        .icon-btn:hover { background: rgba(255,255,255,0.6); color: var(--text-color); border-color: var(--accent-color); transform: translateY(-1px) rotate(10deg); }
        .icon-btn-small { padding: 4px 8px; font-size: 0.9em; border: 1px solid var(--border-color); background: rgba(255,255,255,0.3); color: var(--text-secondary); cursor: pointer; border-radius: 6px; transition: all 0.2s ease; }
        .icon-btn-small:hover { background: rgba(255,255,255,0.6); color: var(--text-color); border-color: var(--accent-color); transform: rotate(15deg); }
        .custom-input-container { max-height: 0; overflow: hidden; opacity: 0; transition: all 0.4s ease-out; margin-top: 0; }
        .custom-input-container.visible { max-height: 100px; opacity: 1; margin-top: 15px; }
        .form-group textarea{resize:vertical;min-height:80px; word-break: break-all;}
        input[type="number"]::-webkit-inner-spin-button, input[type="number"]::-webkit-outer-spin-button { -webkit-appearance: none; margin: 0; }
        input[type=number] { -moz-appearance: textfield; }

        .submit-area{text-align:center;margin-top:30px; display: flex; justify-content: center; gap: 15px; flex-wrap: wrap;}
        .action-btn{border:none;border-radius:8px;padding:12px 25px;font-size:clamp(1em, 3vw, 1.1em);font-family:inherit;font-weight:600;cursor:pointer;transition:all .3s ease;box-shadow:0 2px 15px -4px var(--accent-glow); display: inline-flex; align-items: center; justify-content: center; gap: 10px;}
        #generate-btn{background:var(--accent-color); color: #fff;}
        #reset-form-btn{background:rgba(0, 0, 0, 0.05); color: var(--text-secondary); border: var(--border-width) solid var(--border-color); box-shadow: none;}
        #reset-form-btn:hover {background:rgba(0, 0, 0, 0.1); color: var(--text-color); border-color: var(--accent-color);}
        .action-btn:hover:not(:disabled){transform:translateY(-2px);}
        .action-btn:disabled{background:#E0E0E0;cursor:not-allowed;transform:none;box-shadow:none; opacity: 0.7; color: #9E9E9E;}
        #copy-notification{margin-top:15px;font-size:.9em;color:var(--success-color);opacity:0;transition:opacity .3s ease;height:1em;font-weight:600; width: 100%;}
    </style>
</head>
<body>
    <div class="creator-card-container">
        <div class="creator-card" id="creator-card">
            <header><h2><i class="fa-solid fa-user-pen"></i> 人物档案</h2></header>

            <div class="profile-manager">
                <div class="profile-manager-row"><label for="profile-select"><i class="fa-solid fa-box-archive"></i> 档案:</label><select id="profile-select"><option value="">-- 尚无已存方案 --</option></select></div>
                <div class="profile-manager-row"><div class="profile-manager-group"><button id="load-profile-btn" class="manager-btn" title="读取所选方案"><i class="fa-solid fa-upload"></i> 读取</button><button id="save-profile-btn" class="manager-btn" title="将当前表单内容保存为一个新方案"><i class="fa-solid fa-save"></i> 保存</button><button id="delete-profile-btn" class="manager-btn" title="删除所选方案"><i class="fa-solid fa-trash"></i> 删除</button><button id="import-profiles-btn" class="manager-btn" title="从文件导入方案"><i class="fa-solid fa-file-import"></i> 导入</button><button id="export-profiles-btn" class="manager-btn" title="将所有方案导出为文件"><i class="fa-solid fa-file-export"></i> 导出</button></div></div>
                <input type="file" id="import-file-input" accept=".json" style="display: none;">
            </div>

            <form id="creator-form" onsubmit="return false;">
                <fieldset class="form-section"><legend>基础信息</legend><div class="form-grid"><div class="form-group"><label for="char-name">姓名</label><input type="text" id="char-name" placeholder="你的名字"></div><div class="form-group"><label for="char-race">种族</label><select id="char-race" name="char-race"><option value="人类">人类</option><option value="精灵">精灵</option><option value="猫娘">猫娘</option><option value="龙娘">龙娘</option><option value="狐娘">狐娘</option></select></div><div class="form-group"><label for="char-traits">性格特质</label><input type="text" id="char-traits" placeholder="例如：活泼、傲娇..."></div><div class="form-group"><label for="char-age">年龄</label><input type="number" id="char-age" placeholder="不要填太何意味的年龄！" min="12" max="36"></div></div></fieldset>
                <fieldset class="form-section"><legend>初始物品</legend><div class="form-grid">
                    <div class="form-group">
                        <div class="label-with-button"><label for="appearance-keywords">初始衣物</label><button type="button" id="random-clothing-btn" class="icon-btn-small" title="随机衣物"><i class="fa-solid fa-dice"></i></button></div>
                        <textarea id="appearance-keywords" placeholder="例如：破旧的布衣、华丽的礼裙..."></textarea>
                    </div>
                    <div class="form-group">
                        <div class="label-with-button"><label for="body-keywords">初始物品</label><button type="button" id="random-item-btn" class="icon-btn-small" title="随机物品"><i class="fa-solid fa-dice"></i></button></div>
                        <textarea id="body-keywords" placeholder="例如：一把生锈的铁剑、一个魔法吊坠..."></textarea>
                    </div>
                </div></fieldset>
                <fieldset class="form-section"><legend>故事开端</legend>
                    <div class="form-group full-width"><label for="start-location">开局地点</label><div class="input-with-button"><select id="start-location" name="start-location">
                        <option value="贵族区" selected>贵族区</option>
                        <option value="餐厅">餐厅</option>
                        <option value="贫民窟">贫民窟</option>
                        <option value="南方丘陵">南方丘陵</option>
                        <option value="冒险者工会">冒险者工会</option>
                        <option value="自宅">自宅</option>
                        <option value="custom">自定义</option>
                    </select><button id="random-location-btn" type="button" class="icon-btn" title="随机选择一个地点"><i class="fa-solid fa-dice"></i></button></div></div>
                    <div class="form-group full-width custom-input-container" id="custom-location-container"><input type="text" id="custom-location-input" placeholder="请输入自定义开局地点"></div>

                    <div class="form-group full-width"><label for="char-background">角色背景</label><div class="input-with-button"><select id="char-background" name="char-background">
                        <option value="没落贵族">没落贵族</option>
                        <option value="城郊猎人">城郊猎人</option>
                        <option value="异域旅者">异域旅者</option>
                        <option value="平凡之家">平凡之家</option>
                        <option value="贫民窟孤儿">贫民窟孤儿</option>
                        <option value="custom">自定义</option>
                    </select><button id="random-background-btn" type="button" class="icon-btn" title="随机选择一个背景"><i class="fa-solid fa-dice"></i></button></div></div>
                    <div class="form-group full-width custom-input-container" id="custom-background-container"><input type="text" id="custom-background-input" placeholder="请输入自定义角色背景"></div>
                </fieldset>
                <fieldset class="form-section"><legend>额外备注</legend><div class="form-group full-width"><textarea id="extra-notes" placeholder="如果你有什么其他生成的要求，尽管填写在这里。"></textarea></div></fieldset>

                <div class="submit-area"><button id="generate-btn" type="button" class="action-btn"><i class="fa-solid fa-pen-fancy"></i> <span>完成</span></button><button id="reset-form-btn" type="button" class="action-btn" title="清除当前所有填写内容，重置表单"><i class="fa-solid fa-undo"></i> <span>重置表单</span></button><p id="copy-notification"></p></div>
            </form>
        </div>
    </div>
    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const form = document.getElementById('creator-form');
            const generateBtn = document.getElementById('generate-btn');
            const resetFormBtn = document.getElementById('reset-form-btn');
            const notification = document.getElementById('copy-notification');
            const initialButtonHTML = generateBtn.innerHTML;
            const allInputs = Array.from(form.querySelectorAll('input, textarea, select'));

            const profileSelect = document.getElementById('profile-select');
            const loadProfileBtn = document.getElementById('load-profile-btn');
            const saveProfileBtn = document.getElementById('save-profile-btn');
            const deleteProfileBtn = document.getElementById('delete-profile-btn');
            const exportProfilesBtn = document.getElementById('export-profiles-btn');
            const importProfilesBtn = document.getElementById('import-profiles-btn');
            const importFileInput = document.getElementById('import-file-input');
            const ageInput = document.getElementById('char-age');

            const locationSelect = document.getElementById('start-location');
            const randomLocationBtn = document.getElementById('random-location-btn');
            const customLocationContainer = document.getElementById('custom-location-container');
            const customLocationInput = document.getElementById('custom-location-input');

            const backgroundSelect = document.getElementById('char-background');
            const randomBgBtn = document.getElementById('random-background-btn');
            const customBackgroundContainer = document.getElementById('custom-background-container');
            const customBackgroundInput = document.getElementById('custom-background-input');

            const randomClothingBtn = document.getElementById('random-clothing-btn');
            const clothingTextarea = document.getElementById('appearance-keywords');
            const randomItemBtn = document.getElementById('random-item-btn');
            const itemTextarea = document.getElementById('body-keywords');

            const AUTOSAVE_KEY = 'magicalGirl_AutoSave_v4.2';
            const PROFILE_STORAGE_KEY = 'magicalGirl_ProfileManager_v4.2';
            let saveTimeout;

            const showNotification = (message, color = 'var(--success-color)') => { notification.textContent = message; notification.style.color = color; notification.style.opacity = '1'; clearTimeout(notification.timeoutId); notification.timeoutId = setTimeout(() => { notification.style.opacity = '0'; }, 3500); };
            const getCurrentFormData = () => { const data = {}; allInputs.forEach(input => { const key = input.id || input.name; if(key) data[key] = input.value; }); data['start-location'] = locationSelect.value === 'custom' ? customLocationInput.value : locationSelect.value; data['char-background'] = backgroundSelect.value === 'custom' ? customBackgroundInput.value : backgroundSelect.value; return data; };
            const populateForm = (data) => { if (!data) return; form.reset(); allInputs.forEach(input => { const key = input.id || input.name; if (data[key] !== undefined && input.type !== 'select-one') { input.value = data[key]; } }); const setupCustomSelect = (select, container, input, value) => { const options = Array.from(select.options).map(opt => opt.value); if (options.includes(value)) { select.value = value; } else if (value) { select.value = 'custom'; input.value = value; } select.dispatchEvent(new Event('change')); }; setupCustomSelect(locationSelect, customLocationContainer, customLocationInput, data['start-location']); setupCustomSelect(backgroundSelect, customBackgroundContainer, customBackgroundInput, data['char-background']); allInputs.forEach(input => { if (input.type === 'select-one' && !input.id.includes('location') && !input.id.includes('background') && data[input.id]) { input.value = data[input.id]; } }); };
            const saveAutoSave = () => localStorage.setItem(AUTOSAVE_KEY, JSON.stringify(getCurrentFormData()));
            const debouncedAutoSave = () => { clearTimeout(saveTimeout); saveTimeout = setTimeout(saveAutoSave, 500); };
            const loadAutoSave = () => { const autoSavedData = localStorage.getItem(AUTOSAVE_KEY); if (autoSavedData) { populateForm(JSON.parse(autoSavedData)); showNotification('已自动加载上次编辑的内容。', 'var(--accent-color)'); } };
            const getProfiles = () => JSON.parse(localStorage.getItem(PROFILE_STORAGE_KEY)) || {};
            const saveProfiles = (profiles) => localStorage.setItem(PROFILE_STORAGE_KEY, JSON.stringify(profiles));
            const populateDropdown = () => { const profiles = getProfiles(); const profileNames = Object.keys(profiles); profileSelect.innerHTML = ''; if (profileNames.length === 0) { profileSelect.innerHTML = '<option value="">-- 尚无已存方案 --</option>'; loadProfileBtn.disabled = true; deleteProfileBtn.disabled = true; exportProfilesBtn.disabled = true; } else { profileSelect.innerHTML = '<option value="">-- 选择一个方案 --</option>'; profileNames.sort().forEach(name => { const option = document.createElement('option'); option.value = name; option.textContent = name; profileSelect.appendChild(option); }); loadProfileBtn.disabled = false; deleteProfileBtn.disabled = false; exportProfilesBtn.disabled = false; } };
            form.addEventListener('input', debouncedAutoSave);

            ageInput.addEventListener('input', () => { const min = parseInt(ageInput.min, 10); const max = parseInt(ageInput.max, 10); let value = parseInt(ageInput.value, 10); if (isNaN(value)) return; if (value > max) { ageInput.value = max; } });
            ageInput.addEventListener('blur', () => { const min = parseInt(ageInput.min, 10); let value = parseInt(ageInput.value, 10); if (value < min) { ageInput.value = min; } });

            const handleCustomVisibility = (select, container) => { if (select.value === 'custom') { container.classList.add('visible'); } else { container.classList.remove('visible'); } };
            locationSelect.addEventListener('change', () => handleCustomVisibility(locationSelect, customLocationContainer));
            backgroundSelect.addEventListener('change', () => handleCustomVisibility(backgroundSelect, customBackgroundContainer));

            const addRandomizerToSelect = (button, selectElement) => { button.addEventListener('click', () => { const options = Array.from(selectElement.options).filter(opt => opt.value !== 'custom'); if (options.length > 0) { const randomIndex = Math.floor(Math.random() * options.length); selectElement.value = options[randomIndex].value; selectElement.dispatchEvent(new Event('input', { bubbles: true })); selectElement.dispatchEvent(new Event('change', { bubbles: true })); } }); };
            addRandomizerToSelect(randomLocationBtn, locationSelect);
            addRandomizerToSelect(randomBgBtn, backgroundSelect);

            const addRandomizerToTextarea = (button, textarea, optionsArray) => { button.addEventListener('click', () => { if (optionsArray.length > 0) { const randomIndex = Math.floor(Math.random() * optionsArray.length); textarea.value = optionsArray[randomIndex]; textarea.dispatchEvent(new Event('input', { bubbles: true })); }}); };
            const clothingOptions = ["一件朴素的亚麻长袍", "一套磨损的皮甲", "华丽但略显陈旧的贵族礼服", "一袭轻便的旅行者斗篷", "绣着神秘符文的法师袍"];
            const itemOptions = ["一把生锈的铁匕首", "一个装着草药的旧皮袋", "半瓶劣质治疗药水", "一张看不懂的残破地图", "一块会发出微光的奇特石头"];
            addRandomizerToTextarea(randomClothingBtn, clothingTextarea, clothingOptions);
            addRandomizerToTextarea(randomItemBtn, itemTextarea, itemOptions);

            saveProfileBtn.addEventListener('click', () => { const defaultName = document.getElementById('char-name').value || '未命名方案'; const profileName = prompt('请输入方案名称：', defaultName); if (profileName && profileName.trim() !== '') { const profiles = getProfiles(); profiles[profileName.trim()] = getCurrentFormData(); saveProfiles(profiles); populateDropdown(); profileSelect.value = profileName.trim(); showNotification(`方案 "${profileName.trim()}" 已保存！`); } });
            loadProfileBtn.addEventListener('click', () => { const selectedName = profileSelect.value; if (selectedName) { const profiles = getProfiles(); if (profiles[selectedName]) { populateForm(profiles[selectedName]); debouncedAutoSave(); showNotification(`已读取方案 "${selectedName}"。`); } } else { showNotification('请先从下拉栏中选择一个方案。', 'var(--error-color)'); } });
            deleteProfileBtn.addEventListener('click', () => { const selectedName = profileSelect.value; if (selectedName) { if (confirm(`确定要永久删除方案 "${selectedName}" 吗？此操作无法撤销。`)) { const profiles = getProfiles(); delete profiles[selectedName]; saveProfiles(profiles); populateDropdown(); showNotification(`方案 "${selectedName}" 已被删除。`, 'var(--accent-color)'); } } else { showNotification('请先从下拉栏中选择一个要删除的方案。', 'var(--error-color)'); } });
            exportProfilesBtn.addEventListener('click', () => { const profiles = getProfiles(); if (Object.keys(profiles).length === 0) { showNotification('当前没有任何已存方案可导出。', 'var(--error-color)'); return; } const dataStr = JSON.stringify(profiles, null, 2); const dataBlob = new Blob([dataStr], {type: 'application/json'}); const url = URL.createObjectURL(dataBlob); const a = document.createElement('a'); a.href = url; a.download = `profiles-export-${Date.now()}.json`; document.body.appendChild(a); a.click(); document.body.removeChild(a); URL.revokeObjectURL(url); showNotification('所有方案已成功导出！'); });
            importProfilesBtn.addEventListener('click', () => importFileInput.click());
            importFileInput.addEventListener('change', (event) => { const file = event.target.files[0]; if (!file) return; const reader = new FileReader(); reader.onload = (e) => { try { const importedProfiles = JSON.parse(e.target.result); if (typeof importedProfiles !== 'object' || importedProfiles === null) { throw new Error('无效的文件格式。'); } let currentProfiles = getProfiles(); let importedCount = 0, skippedCount = 0; for (const name in importedProfiles) { if (currentProfiles[name]) { if (confirm(`已存在同名方案 "${name}"，是否要覆盖它？`)) { currentProfiles[name] = importedProfiles[name]; importedCount++; } else { skippedCount++; } } else { currentProfiles[name] = importedProfiles[name]; importedCount++; } } saveProfiles(currentProfiles); populateDropdown(); showNotification(`成功导入 ${importedCount} 个方案，跳过 ${skippedCount} 个。`); } catch (error) { showNotification('导入失败！请确保文件格式正确。', 'var(--error-color)'); } finally { importFileInput.value = ''; } }; reader.readAsText(file); });
            resetFormBtn.addEventListener('click', () => { if (confirm('确定要清空当前所有填写的内容，并将表单重置为默认状态吗？')) { form.reset(); locationSelect.dispatchEvent(new Event('change')); backgroundSelect.dispatchEvent(new Event('change')); debouncedAutoSave(); showNotification('表单已重置为默认状态。', 'var(--accent-color)'); } });

            generateBtn.addEventListener('click', () => {
                saveAutoSave(); generateBtn.disabled = true; generateBtn.innerHTML = `<i class="fa-solid fa-spinner fa-spin"></i> <span>正在生成...</span>`; notification.style.opacity = '0';
                const data = getCurrentFormData();
                const formatValue = (value, defaultValue) => {
                    const trimmedValue = (value || "").toString().trim();
                    const finalValue = trimmedValue || defaultValue;
                    return `"${finalValue.replace(/"/g, '\\"')}"`; // Escape double quotes
                };

                const yamlString = `
<开局><br>
# 除物品外所有变量都**已经存在**，只需要进行’VariableEdit' ，物品则需要'’VariableInsert'<br>
角色档案:<br>
  需要’VariableEdit'的:<br>
    基础.名字: ${formatValue(data['char-name'], '维奥莱塔')}<br>
    基础.年龄: ${formatValue(data['char-age'], '18')}<br>
    基础.性格: ${formatValue(data['char-traits'], '活泼')}<br>
    基础.种族: ${formatValue(data['char-race'], '人类')}<br>
    服饰.衣物: ${formatValue(data['appearance-keywords'], '根据背景自行填写')}<br>
  需要’VariableInsert'的:<br>
    变量路径: 根据下列信息insert'物品栏.物品_1.物品名'、'物品栏.物品_1.描述' 等变量<br>
    初始物品: ${formatValue(data['body-keywords'], '根据背景自行填写')}<br>
故事开端:<br>
    开局地点: ${formatValue(data['start-location'], '根据背景自行填写')}<br>
    角色背景: ${formatValue(data['char-background'], '根据背景自行填写')}<br>
    额外备注: ${formatValue(data['extra-notes'], '无')}<br>
不要立刻引入事件，让维奥莱塔能先观察四周的环境<br>
</开局>`;

                // --- 
                // 新增的行：调用 insertOrAssignVariables 函数
                // --- 
                if (typeof insertOrAssignVariables === 'function') {
                    insertOrAssignVariables({Initialdata: yamlString}, { type: 'chat' });
                } else {
                    console.warn('insertOrAssignVariables function is not defined.');
                }
                // --- 结束新增行 ---

                setTimeout(() => { try { const inputArea = window.parent.document.querySelector('#send_textarea'); const sendButton = window.parent.document.querySelector('#send_but'); if (inputArea && sendButton) { inputArea.value = yamlString; inputArea.dispatchEvent(new Event('input', { bubbles: true })); sendButton.click(); showNotification('档案已发送！等待AI回应...'); generateBtn.innerHTML = `<i class="fa-solid fa-check"></i> <span>已发送</span>`; } else { throw new Error('SillyTavern UI not found.'); } } catch (error) { generateBtn.innerHTML = `<i class="fa-solid fa-xmark"></i> <span>发送失败</span>`; navigator.clipboard.writeText(yamlString).then(() => { showNotification('自动发送失败！已复制到剪贴板。', 'var(--error-color)'); alert('自动发送失败！角色信息已复制到您的剪贴板，请手动粘贴并发送。'); }); } setTimeout(() => { generateBtn.disabled = false; generateBtn.innerHTML = initialButtonHTML; }, 5000); }, 500);
            });
            populateDropdown(); loadAutoSave();
        });
    </script>
</body>
</html>
