<!doctype html>
<html lang="zh-CN">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>定制化ERA状态栏 - 轮回日志 · 浪漫粉</title>
    <style>
      /* 动画效果定义 */
      @keyframes fadeIn { from { opacity: 0; transform: translateY(-15px); } to { opacity: 1; transform: translateY(0); } }
      @keyframes slideDown { from { opacity: 0; transform: translateY(-10px); max-height: 0; } to { opacity: 1; transform: translateY(0); max-height: 100px; } }
      @keyframes modalFadeIn { from { opacity: 0; } to { opacity: 1; } }
      @keyframes modalContentSlideIn { from { opacity: 0; transform: scale(0.95) translateY(-20px); } to { opacity: 1; transform: scale(1) translateY(0); } }

      /* 基础样式 */
      body {
        font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, 'Noto Sans', sans-serif, 'Apple Color Emoji', 'Segoe UI Emoji', 'Segoe UI Symbol', 'Noto Color Emoji';
        margin: 0; padding: 0; background-color: transparent; min-height: 20vh; min-width: 200px; overflow: auto;
      }
      /* 整体容器 */
      .era-statusbar {
        background: linear-gradient(145deg, #fff0f5, #ffe4e1); border-radius: 12px; padding: 16px; margin-top: 15px;
        box-shadow: 0 8px 16px rgba(100, 0, 0, 0.2); border: 1px solid #ffb6c1; overflow-wrap: break-word; word-wrap: break-word; word-break: break-word;
        animation: fadeIn 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94) both;
      }

      /* 折叠标题样式 */
      .era-statusbar-title {
        text-align: center; color: #b71c1c; font-size: clamp(1rem, 4.2vw, 1.15rem); margin: -5px 0 15px 0;
        padding-bottom: 8px; border-bottom: 2px solid rgba(255, 182, 193, 0.5);
        text-shadow: 1px 1px 2px rgba(255,228,225,0.7); animation: slideDown 0.6s ease-out both;
        font-weight: bold; letter-spacing: 1px;
        cursor: pointer; user-select: none; transition: color 0.2s ease;
        list-style: none;
      }
      .era-statusbar-title::-webkit-details-marker { display: none; }
      .era-statusbar-title:hover { color: #d32f2f; }

      /* 两侧箭头样式 */
      .era-statusbar-title::before,
      .era-statusbar-title::after {
        display: inline-block; font-size: 0.8em;
        transition: transform 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
        color: #ef9a9a;
      }
      .era-statusbar-title::before { content: '▸'; margin-right: 12px; }
      .era-statusbar-title::after { content: '◂'; margin-left: 12px; }
