    <script>
      document.addEventListener('DOMContentLoaded', () => {
        // 缓存所有需要操作的 DOM 元素
        const elements = {
          name: document.getElementById('char-name'), title: document.getElementById('char-title'), race: document.getElementById('char-race'), age: document.getElementById('char-age'), virginity: document.getElementById('char-virginity'), firstPartner: document.getElementById('char-first-partner'), innerThoughts: document.getElementById('char-inner-thoughts'),
          inventoryWrapper: document.getElementById('inventory-wrapper'), itemTemplate: document.getElementById('item-template'), inventoryEmptyText: document.getElementById('inventory-empty-text'), inventoryTitleLabel: document.getElementById('inventory-title-label'),
          statusWrapper: document.getElementById('status-wrapper'), statusTemplate: document.getElementById('status-template'), statusEmptyText: document.getElementById('status-empty-text'),
          showEventsBtn: document.getElementById('show-events-btn'), eventsModal: document.getElementById('events-modal'), closeModalBtn: document.querySelector('.era-modal-close-btn'), eventsContent: document.getElementById('events-content'),
          reincarnationCount: document.getElementById('reincarnation-count'),
          clothingOutfit: document.getElementById('clothing-outfit'), clothingFootwear: document.getElementById('clothing-footwear'), clothingAccessory: document.getElementById('clothing-accessory'), clothingRestraint: document.getElementById('clothing-restraint'),
          sceneContent: document.getElementById('scene-content'),
          featureATitle: document.getElementById('feature-a-title'), featureAContent: document.getElementById('feature-a-content'),
          featureBTitle: document.getElementById('feature-b-title'), featureBContent: document.getElementById('feature-b-content'),
          featureCTitle: document.getElementById('feature-c-title'), featureCContent: document.getElementById('feature-c-content'),
          corruptionBar: document.getElementById('corruption-bar'),
          corruptionLabel: document.getElementById('corruption-label'),
          rewindBtn: document.getElementById('rewind-btn'),
        };

        const handleSend = (text) => {
                try {
                    const inputArea = window.parent.document.querySelector('#send_textarea');
                    if (inputArea) {
                        if (inputArea.value.trim().length > 0) {
                            inputArea.value += '\n' + text;
                        } else {
                            inputArea.value = text;
                        }
                        inputArea.dispatchEvent(new Event('input', { bubbles: true }));
                    } else { throw new Error('SillyTavern UI not found.'); }
                } catch (error) {
                    console.error('Error sending message:', error);
                    alert(`自动操作失败，请手动复制: \n\n${text}`);
                }
            };

        elements.showEventsBtn.onclick = () => { elements.eventsModal.style.display = 'flex'; };
        elements.closeModalBtn.onclick = () => { elements.eventsModal.style.display = 'none'; };
        window.onclick = (event) => { if (event.target == elements.eventsModal) { elements.eventsModal.style.display = 'none'; } };
        elements.rewindBtn.onclick = () => {
          if (!elements.rewindBtn.disabled) {
            handleSend('检查主角当前是否处于绝境，若是，发动“轮回回溯”；若否，则主角在脑海里幻想了自己发动“轮回回溯”的场景，并继续推进剧情');
          }
        };

        function updateUI(stat) {
          const charName = _.get(stat, '基础.名字', '角色');
          elements.name.textContent = charName;
          elements.title.textContent = _.get(stat, '临时.称号', '--');
          elements.race.textContent = _.get(stat, '基础.种族', '--');
          elements.age.textContent = _.get(stat, '基础.年龄', '--');

          const corruptionValue = _.get(stat, '临时.堕落值', 0);
          elements.corruptionBar.value = corruptionValue;
          elements.corruptionLabel.textContent = `堕落值: ${corruptionValue}`;

          const canRewind = corruptionValue >= 100;
          elements.rewindBtn.disabled = !canRewind;
          elements.rewindBtn.title = canRewind ? "发动轮回回溯" : "堕落值未满100，无法回溯";

          const charVirginity = _.get(stat, '处女.处女状况', '--');
          elements.virginity.textContent = charVirginity;
          elements.virginity.classList.toggle('text-is-virgin', charVirginity === '是');
          elements.virginity.classList.toggle('text-is-not-virgin', charVirginity !== '是');
          elements.firstPartner.textContent = _.get(stat, '处女.破处者', '暂无');

          elements.innerThoughts.textContent = _.get(stat, '临时.内心想法', '--');
          elements.sceneContent.textContent = _.get(stat, '临时.当前场景', '--');

          elements.clothingOutfit.textContent = _.get(stat, '服饰.衣物', '--');
          elements.clothingFootwear.textContent = _.get(stat, '服饰.鞋袜', '--');
          elements.clothingAccessory.textContent = _.get(stat, '服饰.饰品', '--');
          elements.clothingRestraint.textContent = _.get(stat, '服饰.拘束', '--');

          elements.featureATitle.textContent = _.get(stat, '临时.特写.特写_1.部位', '--');
          elements.featureAContent.textContent = _.get(stat, '临时.特写.特写_1.描述', '--');
          elements.featureBTitle.textContent = _.get(stat, '临时.特写.特写_2.部位', '--');
          elements.featureBContent.textContent = _.get(stat, '临时.特写.特写_2.描述', '--');
          elements.featureCTitle.textContent = _.get(stat, '临时.特写.特写_3.部位', '--');
          elements.featureCContent.textContent = _.get(stat, '临时.特写.特写_3.描述', '--');

          elements.inventoryTitleLabel.textContent = `📦 ${charName}的物品`;
          const inventoryData = _.get(stat, '物品栏');
          let invChildren = elements.inventoryWrapper.children; for (let i = invChildren.length - 1; i >= 0; i--) { const child = invChildren[i]; if (child.id !== 'item-template' && child.id !== 'inventory-empty-text') { elements.inventoryWrapper.removeChild(child); } }
          let itemCount = 0; if (inventoryData && typeof inventoryData === 'object') { for (const key in inventoryData) { if (Object.hasOwnProperty.call(inventoryData, key)) { itemCount++; const item = inventoryData[key]; const itemName = _.get(item, '物品名', '未知物品'); const itemDesc = _.get(item, '描述', '没有描述。');
            const newItemElement = elements.itemTemplate.cloneNode(true); newItemElement.removeAttribute('id'); newItemElement.style.display = 'flex'; const nameElement = newItemElement.querySelector('.inventory-item-name'); const descElement = newItemElement.querySelector('.inventory-item-desc');
            if (nameElement) nameElement.textContent = itemName; if (descElement) descElement.textContent = itemDesc; elements.inventoryWrapper.appendChild(newItemElement);
          } } }
          elements.inventoryEmptyText.style.display = (itemCount === 0) ? 'block' : 'none';

          const statusData = _.get(stat, '状态');
          let statusChildren = elements.statusWrapper.children; for (let i = statusChildren.length - 1; i >= 0; i--) { const child = statusChildren[i]; if (child.id !== 'status-template' && child.id !== 'status-empty-text') { elements.statusWrapper.removeChild(child); } }
          let statusCount = 0; if (statusData && typeof statusData === 'object') { for (const key in statusData) { if (Object.hasOwnProperty.call(statusData, key)) { statusCount++; const status = statusData[key]; const statusName = _.get(status, '状态名', '未知状态'); const statusDesc = _.get(status, '描述', '没有描述。');
            const newStatusElement = elements.statusTemplate.cloneNode(true); newStatusElement.removeAttribute('id'); newStatusElement.style.display = 'flex'; const nameElement = newStatusElement.querySelector('.status-item-name'); const descElement = newStatusElement.querySelector('.status-item-desc');
            if (nameElement) nameElement.textContent = statusName; if (descElement) descElement.textContent = statusDesc; elements.statusWrapper.appendChild(newStatusElement);
          } } }
          elements.statusEmptyText.style.display = (statusCount === 0) ? 'block' : 'none';


          const loopCount = _.get(stat, '轮回回溯.次数', '0');
          elements.reincarnationCount.textContent = `回溯已发动 ${loopCount} 次`;
          const pastEvents = _.get(stat, '轮回回溯.回溯事件');
          elements.eventsContent.innerHTML = '';
          if (pastEvents && typeof pastEvents === 'object' && Object.keys(pastEvents).length > 0) {
            for (const key in pastEvents) { if (Object.hasOwnProperty.call(pastEvents, key)) {
                const eventObj = pastEvents[key]; const eventTitle = _.get(eventObj, '标题', '无标题事件'); const eventContent = _.get(eventObj, '内容', '此事件没有详细内容。');
                const itemWrapper = document.createElement('div'); itemWrapper.className = 'event-item'; const titleElement = document.createElement('h4'); titleElement.className = 'event-title'; titleElement.textContent = eventTitle;
                const contentElement = document.createElement('p'); contentElement.className = 'event-content'; contentElement.textContent = eventContent; itemWrapper.appendChild(titleElement); itemWrapper.appendChild(contentElement); elements.eventsContent.appendChild(itemWrapper);
            } }
          } else { elements.eventsContent.innerHTML = '<p id="events-empty-text">没有可回溯的事件记录。</p>'; }
        }

        eventOn('era:writeDone', (detail) => { if (detail && detail.statWithoutMeta) { updateUI(detail.statWithoutMeta); } });
        eventEmit('era:requestWriteDone');
      });
    </script>
