    <script>
        document.addEventListener('DOMContentLoaded', () => {
            /**
             * 向 SillyTavern 的输入框发送文本。
             * @param {string} text - 要发送的文本。
             */
            const handleSend = (text) => {
                try {
                    const inputArea = window.parent.document.querySelector('#send_textarea');
                    if (inputArea) {
                        if (inputArea.value.trim().length > 0) {
                            inputArea.value += '\n' + text;
                        } else {
                            inputArea.value = text;
                        }
                        inputArea.dispatchEvent(new Event('input', { bubbles: true }));
                    } else {
                        throw new Error('SillyTavern UI not found.');
                    }
                } catch (error) {
                    console.error('Error sending message:', error);
                    alert(`自动操作失败，请手动复制: \n\n${text}`);
                }
            };

            // 绑定所有行动按钮的点击事件
            const actionButtons = document.querySelectorAll('.era-action-btn');
            actionButtons.forEach(button => {
                button.addEventListener('click', () => {
                    const actionText = button.textContent.trim();
                    if (actionText) {
                        handleSend(actionText);
                    }
                });
            });
        });
    </script>
